import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'app/providers.dart';
import 'features/deliveries/domain/delivery.dart';
import 'core/config.dart';
class LoginScreen extends ConsumerStatefulWidget{const LoginScreen({super.key});@override ConsumerState<LoginScreen> createState()=>_LoginState();}
class _LoginState extends ConsumerState<LoginScreen>{final email=TextEditingController(text:Config.demoEmail);final pass=TextEditingController();bool busy=false;String? error;
@override void dispose(){email.dispose();pass.dispose();super.dispose();}
Future<void> submit()async{setState((){busy=true;error=null;});try{await ref.read(apiProvider).login(email.text.trim(),pass.text);ref.read(sessionProvider.notifier).state=true;ref.read(syncProvider).start();}catch(e){setState(()=>error='Login failed. Check credentials and API connection.');}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext context)=>Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.local_shipping,size:64,color:Colors.teal),const SizedBox(height:14),Text('KhojLive Driver',style:Theme.of(context).textTheme.headlineMedium,textAlign:TextAlign.center),const SizedBox(height:20),TextField(controller:email,decoration:const InputDecoration(labelText:'Email')),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),const SizedBox(height:20),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Signing in...':'Sign in'))])))));
}
class DriverHome extends ConsumerStatefulWidget{const DriverHome({super.key});@override ConsumerState<DriverHome> createState()=>_DriverHomeState();}
class _DriverHomeState extends ConsumerState<DriverHome>{List<Delivery> deliveries=[];bool online=false;String? error;int pending=0;Timer? timer;
@override void initState(){super.initState();Future.microtask(load);timer=Timer.periodic(const Duration(seconds:10),(_)=>load());}
@override void dispose(){timer?.cancel();super.dispose();}
Future<void> load()async{try{final result=await ref.read(apiProvider).dio.get('/deliveries');await ref.read(storeProvider).storeDeliveries(result.data as List);final me=await ref.read(apiProvider).dio.get('/drivers/me');online=me.data['availability']=='online';error=null;}catch(_){error='Offline: showing locally cached deliveries';}final local=await ref.read(storeProvider).deliveries();final count=await ref.read(storeProvider).pendingCount();if(mounted)setState((){deliveries=local;pending=count;});}
Future<void> setOnline(bool value)async{try{await ref.read(apiProvider).dio.patch('/drivers/status',data:{'status':value?'online':'offline'});if(value){await ref.read(locationProvider).start();}else{await ref.read(locationProvider).stop();}setState(()=>online=value);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Cannot change availability: $e')));}}
Future<void> advance(Delivery d,DeliveryStatus status)async{await ref.read(storeProvider).enqueueTransition(d,status,reason:status==DeliveryStatus.cancelled?'Driver cancellation':null);await ref.read(syncProvider).sync();await load();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('KhojLive · Driver'),actions:[IconButton(tooltip:'Synchronize',onPressed:()async{await ref.read(syncProvider).sync();await load();},icon:const Icon(Icons.sync)),IconButton(tooltip:'Logout',onPressed:()async{await ref.read(locationProvider).stop();ref.read(syncProvider).stop();await ref.read(apiProvider).logout();ref.read(sessionProvider.notifier).state=false;},icon:const Icon(Icons.logout))]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Row(children:[const Icon(Icons.local_shipping,size:32),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Driver availability',style:TextStyle(fontWeight:FontWeight.bold)),Text(online?'Online · Location tracking active':'Offline')])),Switch(value:online,onChanged:setOnline)]))),if(error!=null)Padding(padding:const EdgeInsets.all(8),child:Text(error!,style:const TextStyle(color:Colors.deepOrange))),ListTile(title:const Text('Assigned deliveries'),subtitle:Text('$pending pending sync operation(s)')),if(deliveries.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(24),child:Text('No deliveries cached. Sign in to load jobs.'))),...deliveries.map((d)=>DeliveryCard(delivery:d,onNext:(s)=>advance(d,s)))])));
}
class DeliveryCard extends ConsumerWidget{final Delivery delivery;final ValueChanged<DeliveryStatus> onNext;const DeliveryCard({super.key,required this.delivery,required this.onNext});
@override Widget build(BuildContext context,WidgetRef ref){final d=delivery;return FutureBuilder<String?>(future:ref.read(storeProvider).pendingStatus(d.id),builder:(ctx,snap){final pending=snap.data;final status=pending==null?d.status:DeliveryStatus.values.byName(pending);final next=allowed[status]?.where((s)=>s!=DeliveryStatus.cancelled).firstOrNull;return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(d.trackingCode,style:Theme.of(context).textTheme.titleLarge),Text('${d.pickup} → ${d.destination}'),const SizedBox(height:8),Chip(label:Text(status.name.replaceAll('_',' '))),if(pending!=null)const Text('Pending server sync',style:TextStyle(color:Colors.deepOrange)),if(next!=null)Align(alignment:Alignment.centerRight,child:FilledButton(onPressed:pending!=null?null:()=>onNext(next),child:Text('Mark ${next.name.replaceAll('_',' ')}')))])));});}
}
